items=json.loads((R/'manifest.json').read_text(encoding='utf-8'))
briefs=[];lines=['# Resources: reader intent analysis','', 'Six article briefs, recorded October 22, 2026. The original planning notes supplied the initial search-intent evidence; these briefs make the editorial decisions explicit. Search volume estimates were not independently remeasured.','']
for it in items:
 id=it['id'];query,kind,intent,scope,success,decision=DATA[id]
 doc=BeautifulSoup((R/'articles'/f'{id}.wp.html').read_text(encoding='utf-8'),'html.parser')
 headings=[h.get_text(' ',strip=True) for h in doc.select('h2')]
 b=dict(title=it['title'],likely_query=query,article_type=kind,intent=intent,outline=headings,out_of_scope=scope,success=success,editorial_decision=decision)
 briefs.append(b)
 lines+=['## '+it['title'],'','- Likely query: '+query,'- Intent and type: '+kind+'. '+intent,'- Outline: '+'; '.join(headings),'- Out of scope: '+scope,'- Success: '+success,'- Editorial decision: '+decision,'']
(R/'reader-intent.json').write_text(json.dumps(briefs,indent=2),encoding='utf-8')
(R/'READER-INTENT.md').write_text('\n'.join(lines),encoding='utf-8')
print('Saved six intent briefs')
